  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Un dossier En cours sans relance datée et sans modification depuis plus de 21 jours est dans « Dossiers sans mouvement ». « Toujours en cours » le marque vu et le fait revenir après 21 jours ; il n'est pas dans « Ma journée » puisqu'il n'a pas de date (leçon 2, Explication simple).$academy_seed$);
