  values (v_ver, v_l2, $academy_seed$m12-q07$academy_seed$, $academy_seed$cas_court$academy_seed$, $academy_seed$Tracer un échange au bon endroit$academy_seed$, $academy_seed$Cas fictif. Monsieur Delorme vous appelle pour signaler qu'il vend son appartement dans trois mois. Aucun statut ne change, aucune action n'est à dater pour l'instant. Où tracez-vous cette information ?$academy_seed$, $academy_seed$["Dans le champ « Notes » du dossier, en écrasant le texte existant","Dans l'Agenda, avec « Nouvelle relance »","Sur la fiche client, onglet « Historique », « + Consigner un échange » avec Type « Appel » et Sens « Entrant »","Dans « Prochaine action », sans date"]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 2, $academy_seed$Un échange se consigne dans l'onglet « Historique » de la fiche client, ce qui l'inscrit dans la chronologie de la relation. L'Agenda crée un événement Google, et une prochaine action sans date n'apparaît nulle part (leçon 2, Explication simple et En rendez-vous).$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l3, $academy_seed$m12-q08$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Signer proprement : réagir au verrou de fiche$academy_seed$, $academy_seed$Cas fictif. Vous enregistrez le dossier de Madame Roussel en Signé, produit et « Date de signature effective » renseignés. Le toast affiche « Pour signer, complétez la fiche client : revenus annuels. » Que faites-vous ?$academy_seed$, $academy_seed$["Repasser le dossier En cours et le signer plus tard, sans rien changer","Saisir 0 dans « Revenus annuels (€) » pour passer le verrou","Renseigner « Revenus annuels (€) » dans « Données client pour la signature », puis « Enregistrer » à nouveau","Demander à la direction de forcer la signature depuis « Vue cabinet »"]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 2, $academy_seed$Le verrou de fiche exige les six champs, dont les revenus annuels ; on les saisit dans « Données client pour la signature » puis on réenregistre. Saisir 0 passe le verrou, car le CRM tient un montant à 0 pour une donnée saisie, mais c'est une fiche fausse que la direction lit dans « Complétude des fiches » et qui trompe le Multi-équipement ; il n'existe pas de signature forcée, la « Vue cabinet » ne fait que lire (leçon 3, Explication simple et Erreur fréquente).$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l3, $academy_seed$m12-q09$academy_seed$, $academy_seed$vrai_faux$academy_seed$, $academy_seed$Partager un dossier : conséquence affichée du co-conseiller$academy_seed$, $academy_seed$Vrai ou faux : sélectionner un « Co-conseiller » dans « Équipe & suivi » n'a aucune conséquence affichée dans la modale.$academy_seed$, $academy_seed$["Vrai","Faux"]$academy_seed$::jsonb, 1)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 1, $academy_seed$Faux. La modale affiche « ⚠ Commission divisée par 2 entre les 2 conseillers » dès qu'un co-conseiller est sélectionné, et les deux conseillers voient ensuite le dossier et la fiche (leçon 3, Explication simple).$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l3, $academy_seed$m12-q10$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$Rendre compte : savoir ce que la direction lit$academy_seed$, $academy_seed$La direction veut voir, conseiller par conseiller, le nombre de fiches, le score moyen de complétude et les champs les plus souvent manquants. Dans quel écran trouve-t-elle ce tableau ?$academy_seed$, $academy_seed$["Onglet « Équipe », tableau « Complétude des fiches »","Écran Pipeline, filtre « Tous les conseillers »","Annuaire des clients, filtre « Mes clients »","Écran « Multi-équipement », chip « À proposer »"]$academy_seed$::jsonb, 3)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 0, $academy_seed$Le tableau « Complétude des fiches » (Conseiller, Fiches, Score moyen, Complètes, « Champs les plus souvent manquants ») est en bas de l'onglet « Équipe », réservé au manager et sans aucun montant. Le filtre du pipeline ne montre que les dossiers (leçon 3, Explication simple).$academy_seed$);
end
